import{_ as n,C as i,o as l,c as d,j as e,a,G as s,ai as r}from"./chunks/framework.CUYGB37K.js";const b=JSON.parse('{"title":"AI Agent Chat","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/ai-agent/ai-agent-chat.md","filePath":"2.0/ai-agent/ai-agent-chat.md","lastUpdated":1776149834000}'),u={name:"2.0/ai-agent/ai-agent-chat.md"};function c(p,t,g,h,m,f){const o=i("ImagePopup");return l(),d("div",null,[t[0]||(t[0]=e("h1",{id:"ai-agent-chat",tabindex:"-1"},[a("AI Agent Chat "),e("a",{class:"header-anchor",href:"#ai-agent-chat","aria-label":'Permalink to "AI Agent Chat"'},"​")],-1)),t[1]||(t[1]=e("p",null,"The AI Agent Chat is your conversational interface for performing PIM operations. Through this chat window, you can interact with the AI Agent using natural language to manage products, categories, data quality, and more.",-1)),t[2]||(t[2]=e("h2",{id:"opening-the-ai-agent-chat",tabindex:"-1"},[a("Opening the AI Agent Chat "),e("a",{class:"header-anchor",href:"#opening-the-ai-agent-chat","aria-label":'Permalink to "Opening the AI Agent Chat"'},"​")],-1)),t[3]||(t[3]=e("p",null,[a("To open the AI Agent Chat, click the "),e("strong",null,'"Open Agenting PIM"'),a(" button located at the bottom-right corner of any page in the admin panel.")],-1)),s(o,{src:"/assets/2.0/images/ai-agent/ai-agent-chat.png",alt:"AI Agent Chat"}),t[4]||(t[4]=r("<p>The AI Agent panel header includes an <strong>AI Settings</strong> link that navigates to <code>/admin/ai-agent/settings</code>, where you can configure AI providers, models, and tool-level permissions.</p><p>The AI Agent panel includes three tabs:</p><ul><li><strong>Capabilities</strong> — Browse the 23 available PIM tools.</li><li><strong>Chat</strong> — Conversational interface to interact with the AI using natural language.</li><li><strong>Sessions</strong> — View and manage your past chat sessions.</li></ul>",3)),s(o,{src:"/assets/2.0/images/ai-agent/ai-agent-chat-tab.png",alt:"AI Agent Chat Tab"}),t[5]||(t[5]=r('<p>Once opened, the chat panel slides in from the right side of the screen. You can start typing your request immediately.</p><h2 id="capabilities-tab" tabindex="-1">Capabilities Tab <a class="header-anchor" href="#capabilities-tab" aria-label="Permalink to &quot;Capabilities Tab&quot;">​</a></h2><p>The Capabilities tab lists all 23 tools the AI Agent can use. Each tool represents a specific PIM operation you can invoke through natural language. The full list is:</p><table tabindex="0"><thead><tr><th>#</th><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td>1</td><td><strong>Create from Image</strong></td><td>Upload photos to auto-create products</td></tr><tr><td>2</td><td><strong>Update Products</strong></td><td>Update attributes/status by SKU</td></tr><tr><td>3</td><td><strong>Search Products</strong></td><td>Find products by SKU, name, or status</td></tr><tr><td>4</td><td><strong>Find Similar</strong></td><td>Find similar products using AI</td></tr><tr><td>5</td><td><strong>Generate Content</strong></td><td>AI-generated name, description &amp; SEO</td></tr><tr><td>6</td><td><strong>Generate Image</strong></td><td>Create product images from text</td></tr><tr><td>7</td><td><strong>Edit Product Image</strong></td><td>Background removal, enhance &amp; retouch</td></tr><tr><td>8</td><td><strong>Assign Categories</strong></td><td>Assign category paths to products</td></tr><tr><td>9</td><td><strong>List Attributes</strong></td><td>View family attributes &amp; options</td></tr><tr><td>10</td><td><strong>Export Products</strong></td><td>Generate CSV/XLSX export</td></tr><tr><td>11</td><td><strong>Bulk Import CSV</strong></td><td>Upload CSV/XLSX to batch update</td></tr><tr><td>12</td><td><strong>Delete Products</strong></td><td>Remove products by SKU list</td></tr><tr><td>13</td><td><strong>Create Category</strong></td><td>Add new categories to the catalog</td></tr><tr><td>14</td><td><strong>Category Tree</strong></td><td>View full category hierarchy</td></tr><tr><td>15</td><td><strong>Create Attribute</strong></td><td>Add new product attributes</td></tr><tr><td>16</td><td><strong>Manage Options</strong></td><td>Add or list attribute options</td></tr><tr><td>17</td><td><strong>Attribute Families</strong></td><td>List, create, or inspect families</td></tr><tr><td>18</td><td><strong>Bulk Edit</strong></td><td>Mass update products by rules</td></tr><tr><td>19</td><td><strong>Catalog Summary</strong></td><td>Stats, counts &amp; recent activity</td></tr><tr><td>20</td><td><strong>Channels</strong></td><td>View channels, locales &amp; currencies</td></tr><tr><td>21</td><td><strong>Users</strong></td><td>View admin users &amp; details</td></tr><tr><td>22</td><td><strong>Roles</strong></td><td>View roles &amp; permissions</td></tr><tr><td>23</td><td><strong>Ask Anything</strong></td><td>Free-form PIM assistant</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Each tool respects your ACL permissions. If your admin role does not have access to a particular operation, the corresponding tool will not execute.</p></div><h2 id="chat-interface-layout" tabindex="-1">Chat Interface Layout <a class="header-anchor" href="#chat-interface-layout" aria-label="Permalink to &quot;Chat Interface Layout&quot;">​</a></h2><p>The chat interface consists of the following areas:</p><ul><li><strong>Message Area</strong> — Displays the conversation history between you and the AI Agent, including responses, tool outputs, and status updates.</li><li><strong>Input Field</strong> — A text input at the bottom where you type your commands or questions.</li><li><strong>Send Button</strong> — Submits your message to the AI Agent for processing.</li></ul><h2 id="types-of-commands" tabindex="-1">Types of Commands <a class="header-anchor" href="#types-of-commands" aria-label="Permalink to &quot;Types of Commands&quot;">​</a></h2><p>You can use the AI Agent Chat for a wide range of PIM operations. Below are the main categories of commands you can give.</p><h3 id="product-operations" tabindex="-1">Product Operations <a class="header-anchor" href="#product-operations" aria-label="Permalink to &quot;Product Operations&quot;">​</a></h3><p>Create, update, search, and bulk edit products by describing what you need.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Create a simple product with SKU TSHIRT-001 and name Blue T-Shirt&quot;</li><li>&quot;Update the price of product SKU LAPTOP-PRO to 999.99&quot;</li><li>&quot;Search for all products in the Footwear category&quot;</li><li>&quot;Bulk update status to enabled for all products with SKU starting with SHOE&quot;</li></ul><h3 id="category-management" tabindex="-1">Category Management <a class="header-anchor" href="#category-management" aria-label="Permalink to &quot;Category Management&quot;">​</a></h3><p>Manage your category tree through natural language commands.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Show me all root categories&quot;</li><li>&quot;List products assigned to the Electronics category&quot;</li></ul><h3 id="data-quality-reports" tabindex="-1">Data Quality Reports <a class="header-anchor" href="#data-quality-reports" aria-label="Permalink to &quot;Data Quality Reports&quot;">​</a></h3><p>Scan your catalog for missing or incomplete data and receive structured reports.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Run a data quality scan on all products in the Clothing category&quot;</li><li>&quot;Which products are missing a description?&quot;</li><li>&quot;Show me products with completeness score below 50%&quot;</li></ul><h3 id="product-verification-quality-scoring" tabindex="-1">Product Verification &amp; Quality Scoring <a class="header-anchor" href="#product-verification-quality-scoring" aria-label="Permalink to &quot;Product Verification &amp; Quality Scoring&quot;">​</a></h3><p>Verify individual products against quality criteria and receive a completeness score.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Check the completeness of product SKU JACKET-100&quot;</li><li>&quot;Verify data quality for all products in the Default family&quot;</li></ul><h3 id="auto-enrichment" tabindex="-1">Auto-Enrichment <a class="header-anchor" href="#auto-enrichment" aria-label="Permalink to &quot;Auto-Enrichment&quot;">​</a></h3><p>Let the AI Agent generate missing content for your products, such as descriptions and SEO fields.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Generate a short description for product SKU SNEAKER-200&quot;</li><li>&quot;Auto-fill missing meta descriptions for all products in the Accessories category&quot;</li><li>&quot;Enrich the SEO fields for product SKU WATCH-050&quot;</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Auto-enrichment works best when the product already has basic information like a name and category. The AI Agent uses existing data to generate relevant, high-quality content.</p></div><h3 id="task-planning" tabindex="-1">Task Planning <a class="header-anchor" href="#task-planning" aria-label="Permalink to &quot;Task Planning&quot;">​</a></h3><p>For complex operations that involve multiple steps, the AI Agent can create and execute a structured plan.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Plan and execute: update all products in the Summer collection to have a 20% discount and a new promotional description&quot;</li><li>&quot;Create a task plan to review and enrich all products with missing images&quot;</li></ul><h3 id="bulk-transformations" tabindex="-1">Bulk Transformations <a class="header-anchor" href="#bulk-transformations" aria-label="Permalink to &quot;Bulk Transformations&quot;">​</a></h3><p>Apply transformations across multiple products simultaneously.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Bulk update all products with status disabled to enabled&quot;</li><li>&quot;Change the category of all products with SKU prefix LEGACY to the Archive category&quot;</li></ul><h3 id="agent-memory-system" tabindex="-1">Agent Memory System <a class="header-anchor" href="#agent-memory-system" aria-label="Permalink to &quot;Agent Memory System&quot;">​</a></h3><p>The AI Agent includes a memory system that allows it to remember facts and preferences you share during your session. It uses two internal tools for this:</p><ul><li><strong>RememberFact</strong> — Stores a fact or preference you provide so the agent can reference it later.</li><li><strong>RecallMemory</strong> — Retrieves previously stored facts when relevant to your current request.</li></ul><p><strong>Example prompts:</strong></p><ul><li>&quot;Remember that our standard product description format starts with the brand name&quot;</li><li>&quot;Recall what I told you about our naming convention&quot;</li></ul><h3 id="content-feedback-loop" tabindex="-1">Content Feedback Loop <a class="header-anchor" href="#content-feedback-loop" aria-label="Permalink to &quot;Content Feedback Loop&quot;">​</a></h3><p>When the AI Agent generates content (such as product descriptions), you can provide feedback to refine the output. The agent captures your preferences and adjusts its responses accordingly.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;That description is too long, make it shorter and more direct&quot;</li><li>&quot;I prefer a formal tone for product descriptions&quot;</li><li>&quot;Rewrite that but focus more on the material and durability&quot;</li></ul><h2 id="real-time-streaming-responses" tabindex="-1">Real-Time Streaming Responses <a class="header-anchor" href="#real-time-streaming-responses" aria-label="Permalink to &quot;Real-Time Streaming Responses&quot;">​</a></h2><p>As the AI Agent processes your request, the response streams into the chat in real time using <strong>Server-Sent Events (SSE)</strong>. You do not need to wait for the entire response to finish before reading the output. This provides a smooth, responsive experience even for complex operations that take several seconds to complete.</p><h2 id="sessions-tab" tabindex="-1">Sessions Tab <a class="header-anchor" href="#sessions-tab" aria-label="Permalink to &quot;Sessions Tab&quot;">​</a></h2><p>The Sessions tab displays a list of your past chat conversations, making it easy to revisit previous interactions with the AI Agent.</p>',52)),s(o,{src:"/assets/2.0/images/ai-agent/ai-agent-sessions.png",alt:"AI Agent Sessions"}),t[6]||(t[6]=r('<p>Each session entry shows the following details:</p><ul><li><strong>Session title</strong> — A summary or label for the conversation.</li><li><strong>Message count</strong> — The number of messages exchanged in that session.</li><li><strong>Date</strong> — When the session was created or last active.</li></ul><h3 id="managing-sessions" tabindex="-1">Managing Sessions <a class="header-anchor" href="#managing-sessions" aria-label="Permalink to &quot;Managing Sessions&quot;">​</a></h3><ul><li><strong>+ New Session</strong> — Click this button to create a fresh conversation without any prior context. This is useful when you want to start a new task without the AI Agent referencing earlier messages.</li><li><strong>Delete session</strong> — Click the trash icon next to a session to permanently remove it. This action cannot be undone.</li><li><strong>Resume a session</strong> — Click on any session in the list to reopen it. The full conversation history and context are preserved, so the AI Agent picks up exactly where you left off.</li></ul><h3 id="session-persistence" tabindex="-1">Session Persistence <a class="header-anchor" href="#session-persistence" aria-label="Permalink to &quot;Session Persistence&quot;">​</a></h3><p>Sessions are database-backed, which means:</p><ul><li><strong>Page refreshes</strong> do not clear your conversations. When you reload the page, your previous messages and responses are restored.</li><li><strong>Browser sessions</strong> are preserved. You can close your browser and return later to continue where you left off.</li><li><strong>Context is maintained</strong> within a session, so the AI Agent remembers what you discussed earlier in the same conversation.</li><li>Sessions persist across logins, so your conversation history is always available when you sign back in.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Start a new session when switching to a different task. This keeps conversations focused and prevents the AI Agent from mixing context between unrelated operations.</p></div>',8))])}const A=n(u,[["render",c]]);export{b as __pageData,A as default};
